//===================== Test gen matrix ============================

void test_gen_matrix_print() {
  uint8_t test_seed[KYBER_SYMBYTES] = {
    0x00, 0x11, 0x22, 0x33, 0x44, 0x55, 0x66, 0x77,
    0x88, 0x99, 0xaa, 0xbb, 0xcc, 0xdd, 0xee, 0xff,
    0x10, 0x32, 0x54, 0x76, 0x98, 0xba, 0xdc, 0xfe,
    0x01, 0x23, 0x45, 0x67, 0x89, 0xab, 0xcd, 0xef
  };

  polyvec a[KYBER_K];
  gen_matrix(a, test_seed, 0); // 0 = A, không phải A^T

  for (int i = 0; i < KYBER_K; i++) {
    for (int j = 0; j < KYBER_K; j++) {
      printf("\nA[%d][%d]:\n", i, j);
      for (int k = 0; k < KYBER_N; k++) {
        printf("%5d ", a[i].vec[j].coeffs[k]);
        if ((k + 1) % 8 == 0) printf("\n");
      }
      printf("\n\n");
    }
  }
}
//=================== Test key gen ==========================
void test_keypair_gen(void) {
  unsigned long start, end;
  uint8_t pk[KYBER_INDCPA_PUBLICKEYBYTES];
  uint8_t sk[KYBER_INDCPA_SECRETKEYBYTES];
  start = rdcycle();
  indcpa_keypair(pk, sk);
  end = rdcycle();
  printf("\n=== PUBLIC KEY ===\n");
  for (int i = 0; i < KYBER_INDCPA_PUBLICKEYBYTES; i++) {
    printf("%02x", pk[i]);
    if ((i + 1) % 32 == 0) printf("\n");
  }

  printf("\n=== SECRET KEY ===\n");
  for (int i = 0; i < KYBER_INDCPA_SECRETKEYBYTES; i++) {
    printf("%02x", sk[i]);
    if ((i + 1) % 32 == 0) printf("\n");
  }
  printf("Keygen execution took %lu cycles\n", end - start);
}
//================== test NTT =========================
void test_ntt(void) {
unsigned long start, end;
  int16_t poly[256] = {0};
  for (int i = 0; i< 256; i++){
    poly[i] = i;
  }
start = rdcycle();
  poly_ntt_rocc(poly);
end = rdcycle();
  for (int i = 0; i < 256; i++) {
    printf("%d ", poly[i]);
    if ((i+1)%16 == 0) printf("\n");
  }
printf("NTT execution took %lu cycles\n", end - start);
}

