void test_pwm(void){
  unsigned long start, end;
  uint16_t a[KYBER_N];
  uint16_t b[KYBER_N];
  uint16_t c[KYBER_N];
for (int i = 0; i < KYBER_N; i ++) {
  a[i] = i;
  b[i] = 3328 - i;
}

start = rdcycle();
  poly_basemul_rocc(c, a, b);
end = rdcycle();
//  c[0] = barrett_reduce_rocc(a[0] * b[0]);
//  c[1] = barrett_reduce_rocc(a[1] * b[1]);
  for (int i = 0; i < KYBER_N; i++){
     printf("c[%d] = %d\n", i, c[i]);
  }
  printf("Basemul execution took %lu cycles\n", end - start);
}

